$('#toggle').onclick=()=>{list=!list;tick('flip');renderTasks()};$('#sort').onclick=()=>{data.sort=!data.sort;save();renderTasks()};$('#add').onclick=()=>openEditor();$('#sound').onclick=()=>setSoundEnabled(!data.sound);$('#archive').onclick=()=>{archive=!archive;renderTasks()};$('#today').onclick=()=>{selected=today();view='day';$('#calendar').scrollTop=0;renderCalendar()};$('#views').onclick=e=>{if(!e.target.dataset.view)return;view=e.target.dataset.view;renderCalendar();tick('switch')};function navigate(n){let d=new Date(selected+'T12:00:00');if(view==='month'){d.setDate(1);d.setMonth(d.getMonth()+n)}else d.setDate(d.getDate()+n*(view==='week'?7:1));selected=fmt(d);renderCalendar();tick('switch')}$('#prev').onclick=()=>navigate(-1);$('#next').onclick=()=>navigate(1);let sx=0,sy=0;$('#calendar').addEventListener('touchstart',e=>{sx=e.touches[0].clientX;sy=e.touches[0].clientY},{passive:true});$('#calendar').addEventListener('touchend',e=>{if(e.target.closest('.event'))return;let dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.8)navigate(dx<0?1:-1)},{passive:true});function ratio(r){data.ratio=Math.max(.2,Math.min(.55,r));$('#tasks').style.height=data.ratio*100+'%'}ratio(data.ratio||.34);$('#split').onpointerdown=e=>{e.preventDefault();const y=e.clientY,h=$('#tasks').offsetHeight;$('#split').setPointerCapture(e.pointerId);$('#split').onpointermove=ev=>ratio((h+ev.clientY-y)/$('main').clientHeight);$('#split').onpointerup=()=>{$('#split').onpointermove=null;save()}};$('#split').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();ratio(data.ratio+(e.key==='ArrowUp'?-.03:.03));save()}};renderTasks();renderCalendar();

function headerTitle(){return data.headerTitle??((data.name||'香香')+' Weekly')}function renderName(){const title=headerTitle();$('#username').textContent=title;document.title=title+' · 月光塔罗'}renderName();$('#settings').onclick=()=>{$('#name-input').value=headerTitle();$('#settings-dialog').showModal()};$('#settings-dialog form').addEventListener('submit',e=>{if(e.submitter?.value==='save'&&!$('#name-input').value.trim()){e.preventDefault();$('#name-input').setCustomValidity('请填写首页标题');$('#name-input').reportValidity()}});$('#name-input').oninput=()=>$('#name-input').setCustomValidity('');$('#settings-dialog').addEventListener('close',()=>{if($('#settings-dialog').returnValue!=='save')return;data.headerTitle=$('#name-input').value.trim();save();renderName();toast('首页标题已更新')});

