// Follow the visible viewport while the phone keyboard opens and closes.
function syncDialogViewport(){const viewport=window.visualViewport;document.documentElement.style.setProperty('--visual-height',(viewport?.height||window.innerHeight)+'px');document.documentElement.style.setProperty('--visual-top',(viewport?.offsetTop||0)+'px')}
window.visualViewport?.addEventListener('resize',syncDialogViewport);window.visualViewport?.addEventListener('scroll',syncDialogViewport);window.addEventListener('resize',syncDialogViewport);syncDialogViewport();

// Own the touch sequence from its start: native selection/panning cannot take over mid-drag.
function touchCard(e,task,el){
 if(e.touches.length!==1||e.target.closest('button')||task.done)return;
 e.preventDefault();const first=e.touches[0],identifier=first.identifier,x=first.clientX,y=first.clientY,collection=$('#collection'),initialScroll=collection.scrollTop;
 let active=false,moved=false,ghost=null,point={x,y},frame=0,ended=false;
 const touch=ev=>[...ev.touches].find(t=>t.identifier===identifier);
 function stop(){clearTimeout(timer);cancelAnimationFrame(frame);ghost?.remove();document.body.classList.remove('dragging-card');document.removeEventListener('touchmove',move);document.removeEventListener('touchend',end);document.removeEventListener('touchcancel',cancel)}
 function autoScroll(){if(!active||ended)return;const c=$('#calendar'),b=c.getBoundingClientRect();if(point.x>=b.left&&point.x<=b.right&&point.y>=b.top&&point.y<=b.bottom){const edge=32;if(point.y>b.bottom-edge)c.scrollTop+=Math.ceil((point.y-b.bottom+edge)/5);else if(point.y<b.top+edge)c.scrollTop-=Math.ceil((b.top+edge-point.y)/5)}frame=requestAnimationFrame(autoScroll)}
 const timer=setTimeout(()=>{if(moved||ended)return;active=true;window.getSelection()?.removeAllRanges();document.body.classList.add('dragging-card');ghost=document.createElement('div');ghost.className='ghost';ghost.textContent=task.title;document.body.append(ghost);ghost.style.left=point.x-45+'px';ghost.style.top=point.y-30+'px';tick('grab');autoScroll()},420);
 function move(ev){const t=touch(ev);if(!t)return;ev.preventDefault();point={x:t.clientX,y:t.clientY};if(!active){if(Math.hypot(point.x-x,point.y-y)>9){moved=true;clearTimeout(timer)}if(moved)collection.scrollTop=initialScroll+y-point.y;return}ghost.style.left=point.x-45+'px';ghost.style.top=point.y-30+'px'}
 function end(ev){if([...ev.touches].some(t=>t.identifier===identifier))return;ev.preventDefault();ended=true;const last=[...ev.changedTouches].find(t=>t.identifier===identifier);if(last)point={x:last.clientX,y:last.clientY};stop();if(!active){if(!moved)el.click();return}const c=$('#calendar'),b=c.getBoundingClientRect();if(point.x<b.left||point.x>b.right||point.y<b.top||point.y>b.bottom)return;if(view!=='day'){toast('请切换日视图安排具体时间');return}const top=$('.timeline').getBoundingClientRect().top,start=Math.max(0,Math.min(1410,Math.round((point.y-top)/15)*15));data.events.push({id:crypto.randomUUID(),task:task.id,date:selected,start,duration:Math.min(60,1440-start)});if(save())WeeklyAnalytics.track('schedule_created');renderCalendar();toast('已安排，任务卡片仍保留');tick()}
 function cancel(){ended=true;stop()}
 document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',end,{passive:false});document.addEventListener('touchcancel',cancel,{passive:false});
}
document.addEventListener('contextmenu',e=>{if(!e.target.closest('input,textarea'))e.preventDefault()});

function renderArtPicker(selectedArt){const names=['太阳','月亮','希腊神庙','星辰罗盘','月桂竖琴','希腊双耳瓶'];$('#art-picker').open=false;$('#art-picker .art-options').innerHTML=names.map((name,i)=>`<label><input type="radio" name="art" value="${i}" ${i===selectedArt%6?'checked':''}><span>${art(i)}<small>${name}</small></span></label>`).join('')}

// Deletions are reversible without overwriting later edits.
const undoStack=[];let undoTimer,pendingRestore=null;const beforeImportKey=key+'-before-import';
function refreshAll(){soundPlayer.sync();syncSoundControls();selectedEvent=null;renderName();ratio(data.ratio||.34);renderTasks();renderCalendar();updateDataTools()}
function updateDataTools(){$('#undo-last').disabled=!undoStack.length;$('#restore-before-import').disabled=!localStorage.getItem(beforeImportKey)}
function showUndo(message){$('#undo-bar span').textContent=message;$('#undo-bar').hidden=false;clearTimeout(undoTimer);undoTimer=setTimeout(()=>$('#undo-bar').hidden=true,8000);updateDataTools()}
function rememberDeletion(entry){undoStack.push(entry);if(undoStack.length>20)undoStack.shift()}
function deleteTask(task){rememberDeletion({kind:'task',task:JSON.parse(JSON.stringify(task)),index:data.tasks.indexOf(task),events:data.events.filter(e=>e.task===task.id).map(e=>({event:{...e},index:data.events.indexOf(e)}))});data.tasks=data.tasks.filter(t=>t.id!==task.id);data.events=data.events.filter(e=>e.task!==task.id);if(save())WeeklyAnalytics.track('task_deleted');refreshAll();showUndo('已删除任务及其日程');tick('delete')}
function deleteSchedule(event){rememberDeletion({kind:'event',event:{...event},index:data.events.indexOf(event)});data.events=data.events.filter(e=>e.id!==event.id);if(save())WeeklyAnalytics.track('schedule_deleted');refreshAll();showUndo('已移除本次日程');tick('delete')}
function undoDelete(){const item=undoStack.pop();if(!item){toast('本次打开期间没有可撤销的删除');return}if(item.kind==='task'){if(!data.tasks.some(t=>t.id===item.task.id))data.tasks.splice(Math.min(item.index,data.tasks.length),0,item.task);for(const record of item.events)if(!data.events.some(e=>e.id===record.event.id))data.events.splice(Math.min(record.index,data.events.length),0,record.event)}else if(data.tasks.some(t=>t.id===item.event.task)&&!data.events.some(e=>e.id===item.event.id)){data.events.splice(Math.min(item.index,data.events.length),0,item.event)}if(save())WeeklyAnalytics.track('delete_undone');refreshAll();$('#undo-bar').hidden=true;toast('已撤销删除');tick('place')}
$('#undo-action').onclick=undoDelete;$('#undo-last').onclick=undoDelete;$('#undo-close').onclick=()=>$('#undo-bar').hidden=true;
$('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify(WeeklyBackup.makeBackup(data),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Weekly-backup-'+today()+'.json';document.body.append(a);a.click();WeeklyAnalytics.track('backup_export_started');a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('备份已发起下载，请保存文件')};
$('#import-data').onclick=()=>{$('#backup-file').value='';$('#backup-file').click()};
$('#backup-file').onchange=async()=>{const file=$('#backup-file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('文件过大，请选择小于5MB的备份');const validated=WeeklyBackup.validateBackup(JSON.parse(await file.text()));prepareRestore(validated,'备份包含 '+validated.tasks.length+' 个任务、'+validated.events.length+' 条日程。')}catch(error){toast(error instanceof SyntaxError?'文件不是有效的 JSON 备份':error.message)}};
function prepareRestore(validated,summary){pendingRestore=validated;$('#restore-summary').textContent=summary;$('#restore-confirm').showModal()}
$('#restore-cancel').onclick=()=>{$('#restore-confirm').close();pendingRestore=null};$('#restore-confirm').addEventListener('cancel',()=>pendingRestore=null);
$('#restore-apply').onclick=()=>{if(!pendingRestore)return;try{const old=JSON.stringify(WeeklyBackup.makeBackup(data));localStorage.setItem(beforeImportKey,old);localStorage.setItem(key,JSON.stringify(pendingRestore))}catch{toast('存储空间不足，未导入；请先导出当前数据');return}WeeklyAnalytics.track('backup_restored');data=pendingRestore;pendingRestore=null;undoStack.length=0;archive=false;selected=today();view='day';$('#restore-confirm').close();$('#settings-dialog').close('cancel');$('#undo-bar').hidden=true;refreshAll();toast('备份已恢复')};
$('#restore-before-import').onclick=()=>{try{const stored=localStorage.getItem(beforeImportKey);if(!stored){toast('还没有导入前的备份');return}const validated=WeeklyBackup.validateBackup(JSON.parse(stored));prepareRestore(validated,'将恢复上一次导入前保留的 '+validated.tasks.length+' 个任务和 '+validated.events.length+' 条日程。')}catch{toast('导入前备份不可用，当前数据未改变')}};
updateDataTools();

function syncSoundControls(){$('#sound-enabled').checked=!!data.sound;$('#sound-volume').value=Math.round((data.volume??.4)*100);$('#volume-value').textContent=$('#sound-volume').value+'%';$('#sound-preview').querySelectorAll('button').forEach(b=>b.disabled=!data.sound||+$('#sound-volume').value===0)}
function setSoundEnabled(enabled){data.sound=enabled;soundPlayer.sync();save();renderTasks();syncSoundControls();if(enabled)tick('place');toast(enabled?'音效已开启':'音效已关闭')}
$('#sound-enabled').onchange=e=>setSoundEnabled(e.target.checked);
$('#sound-volume').oninput=e=>{data.volume=Number(e.target.value)/100;soundPlayer.sync();save();syncSoundControls()};$('#sound-volume').onchange=()=>tick('place');
$('#sound-preview').onclick=e=>{const kind=e.target.closest('button')?.dataset.sound;if(kind)tick(kind)};
syncSoundControls();

document.addEventListener('pointerdown',()=>soundPlayer.unlock(),{passive:true});document.addEventListener('touchstart',()=>soundPlayer.unlock(),{passive:true});

$('#analytics-enabled').checked=WeeklyAnalytics.isEnabled();$('#analytics-enabled').onchange=e=>{WeeklyAnalytics.setEnabled(e.target.checked);toast(e.target.checked?'使用统计已开启':'使用统计已关闭')};
